import { makeCppBlitz } from './builders.mjs';

/**
 * 90 unique C++ 1v1 Quick Blitz questions (10 per Easy/Med/Hard × 3m/5m/10m).
 * All problems use clean standard C++ headers and stdin boilerplate so players finish 30-45s early.
 */
function cppSpec(id, difficulty, durationSecs, title, description, headers, inputReader, starterTodo, implBody, testCases) {
  const hdrs = ['#include <iostream>', ...headers].join('\n');
  const build = (body) =>
    `${hdrs}\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n${inputReader}\n${body}\n    return 0;\n}\n`;
  return makeCppBlitz({
    id,
    title,
    difficulty,
    durationSecs,
    description,
    starterBody: build(starterTodo),
    solutionCode: build(implBody),
    testCases,
  });
}

const READ_VEC_LINE = `    string _line;\n    getline(cin, _line);\n    stringstream _ss(_line);\n    vector<long long> arr;\n    long long _v;\n    while (_ss >> _v) arr.push_back(_v);`;
const READ_N_ARR = `    int n; cin >> n;\n    vector<long long> arr(n);\n    for (int i = 0; i < n; ++i) cin >> arr[i];`;
const READ_K_N_ARR = `    long long k; int n; cin >> k >> n;\n    vector<long long> arr(n);\n    for (int i = 0; i < n; ++i) cin >> arr[i];`;

